const location    = $('Split In Batches (Locations)').item.json;
const provider    = $('find region id').first().json;
const plannedData = $('Yasno Planned API').first().json;
const probableData = $('Yasno Probable API').first().json;

const outageGroup = location.outage_group;
const regionId    = provider.regionId.toString();
const dsoId       = provider.dsoId.toString();

const resultSlots = [];

function getKyivOffsetMinutes(dateStr) {
  const formatter = new Intl.DateTimeFormat('en', {
    timeZone: 'Europe/Kyiv',
    timeZoneName: 'longOffset'
  });
  const parts = formatter.formatToParts(new Date(`${dateStr}T12:00:00Z`));
  const tzName = parts.find(p => p.type === 'timeZoneName')?.value ?? 'GMT+02:00';
  const match  = tzName.match(/GMT([+-])(\d{2}):(\d{2})/);
  if (!match) return 120;
  const sign = match[1] === '+' ? 1 : -1;
  return sign * (parseInt(match[2]) * 60 + parseInt(match[3]));
}

function buildSlot(locationId, dateStr, slot, source) {
  const offsetMins = getKyivOffsetMinutes(dateStr);
  const startDate = new Date(`${dateStr}T00:00:00Z`);
  startDate.setUTCMinutes(startDate.getUTCMinutes() - offsetMins + slot.start);
  const endDate = new Date(`${dateStr}T00:00:00Z`);
  endDate.setUTCMinutes(endDate.getUTCMinutes() - offsetMins + slot.end);
  return {
    location_id:   locationId,
    planned_start: startDate.toISOString(),
    planned_end:   endDate.toISOString(),
    is_confirmed:  false,
    source:        source
  };
}

if (plannedData && typeof plannedData === 'object' && !plannedData.error) {
  for (const dayKey of ['today', 'tomorrow']) {
    const day = plannedData[outageGroup]?.[dayKey];
    if (!day) continue;

    const dateStr = day.date.split('T')[0];

    if (day.status === 'NoOutages') {
      continue;

    } else if (day.status === 'ScheduleApplies') {
      for (const slot of day.slots) {
        if (slot.type !== 'Definite') continue;
        resultSlots.push(buildSlot(location.id, dateStr, slot, 'yasno'));
      }

    } else if (day.status === 'WaitingForSchedule' && probableData && !probableData.error) {
      const jsDay = new Date(`${dateStr}T12:00:00Z`).getDay();
      const dayOfWeek = (jsDay === 0 ? 6 : jsDay - 1).toString();
      const probableSlots = probableData[regionId]
        ?.dsos?.[dsoId]
        ?.groups?.[outageGroup]
        ?.slots?.[dayOfWeek] ?? [];

      for (const slot of probableSlots) {
        if (slot.type !== 'Definite') continue;
        resultSlots.push(buildSlot(location.id, dateStr, slot, 'probable'));
      }
    }
  }
}

return resultSlots.length > 0
  ? resultSlots.map(s => ({ json: s }))
  : [{ json: { location_id: location.id, no_outages: true } }];

// 1. Получаем данные ТЕКУЩЕЙ локации из цикла
const location = $('Split In Batches (Locations)').item.json;

const providerRegionId = location.provider_region_id; // ID связи из таблицы locations

// 2. Получаем ВСЕ элементы из ноды 'Get Provider' как массив
const allProviders = $('Get Providers').all();

// 3. Ищем внутри массива нужный провайдер по ID
const matchedProvider = allProviders.find(item => item.json.id === providerRegionId);

if (!matchedProvider) {
  throw new Error(`Налаштування провайдера для ID ${providerRegionId} не знайдені в таблиці provider_regions`);
}


return [{
  json: {
    regionId: matchedProvider.json.region_id,
    dsoId: matchedProvider.json.dso_id
  }
}];
